    char *name = NULL;
    struct invalid_entry_data *data = NULL;
    int result = -EINVAL;

    if (!fc || !cs) {
        return -EINVAL;
    }

    if (size < sizeof(struct invalid_entry_data)) {
        goto out;
    }

    data = malloc(size);
    if (!data) {
        result = -ENOMEM;
        goto out;
    }

    if (fuse_copy_in(cs, data, size, 0) < 0) {
        goto free_data;
    }

    name = data->name;

    if (strlen(name) + 1 > data->name_len) {
        result = -EINVAL;
        goto free_data;
    }

    if (data->name_len + sizeof(struct invalid_entry_data) != size) {
        result = -EINVAL;
        goto free_data;
    }

