    if (fuse_copy_state_read(cs, name, out->name_len)) {
        ret = -EFAULT;
        goto out_free_out;
    }

    compute_hash(name, out->hash);

    ret = fuse_reverse_invalid_entry(fc, out);

    if (ret < 0)
        goto out_free_out;

