int handle_invalid_entry(struct fuse_conn *fc, unsigned int size, struct fuse_copy_state *cs) {
    char *name = NULL;
    struct output_data *out = NULL;
    int ret = -EINVAL;

    if (!fc || !cs) {
        return -EINVAL;
    }

    name = (char *)malloc(size + 1);
    if (!name) {
        return -ENOMEM;
    }

    if (fuse_copy_in(cs, name, size, 0) != size) {
        goto out;
    }

    name[size] = '\0';

    out = (struct output_data *)malloc(sizeof(struct output_data));
    if (!out) {
        ret = -ENOMEM;
        goto out;
    }

    if (strlen(name) > MAX_NAME_LEN) {
        ret = -ENAMETOOLONG;
        goto out;
    }

    out->name = strdup(name);
    if (!out->name) {
        ret = -ENOMEM;
        goto out;
    }

    out->hash = compute_hash(name);
    ret = reverse_invalid_entry(fc, out);

out:
    free(name);
    if (out) {
        free(out->name);
        free(out);
    }

    return ret;
}

int handle_invalid_entry(struct fuse_conn *fc, unsigned int size, struct fuse_copy_state *cs) {
    char *name = NULL;
    struct invalid_entry_data *out = NULL;
    int result = 0;
    size_t name_len;

    // Allocate buffer for name
    name = malloc(size);
    if (!name) {
        return -ENOMEM;
    }

    // Validate input size
    if (size == 0 || size > FUSE_NAME_MAX) {
        result = -EINVAL;
        goto cleanup;
    }

    // Copy data into output structure
    out = malloc(sizeof(*out));
    if (!out) {
        result = -ENOMEM;
        goto cleanup;
    }

    if (fuse_copy_in(name, size, cs) != 0) {
        result = -EFAULT;
        goto cleanup;
    }

    name_len = strlen(name);
    if (name_len == 0 || name_len >= size) {
        result = -EINVAL;
        goto cleanup;
    }

    // Compute hash
    uint32_t hash = compute_name_hash(name, name_len);

    // Attempt to reverse the invalid entry
    if (reverse_entry(fc, hash, name, name_len) != 0) {
        result = -EFAULT;
    }

cleanup:
    free(name);
    free(out);
    return result;
}
